static double inline_model_tree_predict(const inline_tree_node_t* nodes, const double* x) {
    int i = 0;
    while (nodes[i].feature >= 0) {
        i = (x[nodes[i].feature] <= nodes[i].threshold) ? nodes[i].left : nodes[i].right;
    }
    return nodes[i].probability;
}

double inline_model_predict_proba(const double* x) {
    double sum = 0.0;
    for (int t = 0; t < INLINE_MODEL_TREE_COUNT; ++t) {
        inline_tree_info_t info = INLINE_MODEL_TREES[t];
        sum += inline_model_tree_predict(&INLINE_MODEL_NODES[info.offset], x);
    }
    return sum / (double)INLINE_MODEL_TREE_COUNT;
}

int inline_model_predict(const double* x) {
    return inline_model_predict_proba(x) >= INLINE_MODEL_THRESHOLD;
}
